  "labels": [
    {
      "label": "T_Grinding",
      "span": "you'll be doing chores in order to get to them",
      "rule_applied": "Grinding definition and boundary rule: the span identifies tedious tasks required to make progress toward desired game content.",
      "rationale": "The reviewer describes having to perform chore-like in-game work before reaching the puzzles."
    }
  ],
  "invoked_web_search": false,
